# RGB-derived: docs/fasten_screws/applied_values.json (rgb_derived_values).
# RGB updates generated by --run-geometry-fitting.
# Evidence: docs/fasten_screws/geometry_fit.json
"""Coarse RGB detector for nuts and bolts in RoboDojo fasten_screws."""
import math
import numpy as np
from scipy import ndimage
REF_WIDTH = 640.0
REF_HEIGHT = 480.0
DEFAULT_CX = 320.0
DEFAULT_CY = 240.0
DEFAULT_FX = 288.1325378417969
DEFAULT_FY = 288.1325378417969

def _extract_intrinsics(camera_meta, width, height):
    """Extract (fx, fy, cx, cy) scaled to image dimensions."""
    sx = float(width) / REF_WIDTH
    sy = float(height) / REF_HEIGHT
    fx = DEFAULT_FX * sx
    fy = DEFAULT_FY * sy
    cx = DEFAULT_CX * sx
    cy = DEFAULT_CY * sy
    if isinstance(camera_meta, dict):
        intr = camera_meta.get('intrinsics', camera_meta.get('K'))
        if intr is not None:
            arr = np.asarray(intr, dtype=np.float64)
            if arr.shape == (3, 3):
                fx = float(arr[0, 0])
                fy = float(arr[1, 1])
                cx = float(arr[0, 2])
                cy = float(arr[1, 2])
    return (fx, fy, cx, cy)

def _build_workspace_and_gripper_masks(img):
    """Build valid tabletop workspace mask and dark robot gripper mask."""
    h, w = img.shape[:2]
    sx = float(w) / REF_WIDTH
    sy = float(h) / REF_HEIGHT
    yy, xx = np.indices((h, w))
    roi = np.ones((h, w), dtype=bool)
    left_wrist = (xx < int(round(124 * sx))) & (yy > int(round(262 * sy)))
    right_wrist = (xx >= int(round(526 * sx))) & (yy > int(round(264 * sy)))
    left_palm = (xx < int(round(140 * sx))) & (yy > int(round(284 * sy)))
    right_palm = (xx > int(round(502 * sx))) & (yy > int(round(284 * sy)))
    roi = roi & ~left_wrist & ~right_wrist & ~left_palm & ~right_palm
    r = img[:, :, 0]
    g = img[:, :, 1]
    b = img[:, :, 2]
    vmax = np.maximum(np.maximum(r, g), b)
    vmin = np.minimum(np.minimum(r, g), b)
    chroma = vmax - vmin
    raw_dark = (vmax < 108.0) & (chroma < 44.0) & (yy > int(round(236 * sy)))
    lbl, num = ndimage.label(raw_dark)
    if num > 0:
        counts = np.bincount(lbl.ravel())
        min_gripper_area = max(45, int(round(55 * sx * sy)))
        keep = counts >= min_gripper_area
        keep[0] = False
        gripper_mask = keep[lbl]
    else:
        gripper_mask = np.zeros((h, w), dtype=bool)
    return (roi, gripper_mask)

def _compute_color_channels(img, roi, gripper_mask):
    """Segment foreground candidates per color class and compute response maps."""
    r = img[:, :, 0]
    g = img[:, :, 1]
    b = img[:, :, 2]
    vmax = np.maximum(np.maximum(r, g), b)
    vmin = np.minimum(np.minimum(r, g), b)
    chroma = vmax - vmin
    valid = roi & ~gripper_mask
    mask_white = valid & (r > 152.0) & (g > 152.0) & (b > 146.0) & (chroma < 42.0)
    score_white = vmin - 0.5 * chroma
    mask_red = valid & (r > 150.0) & (r - g > 82.0) & (r - b > 82.0) & (r - 1.55 * g > 55.0)
    score_red = r - 1.15 * g - 0.25 * b
    mask_yellow = valid & (r > 142.0) & (g > 122.0) & (b < 95.0) & (g - b > 72.0) & (r - b > 90.0) & (g > 0.72 * r)
    score_yellow = np.minimum(r, g) - b
    mask_blue = valid & (b > 98.0) & (b - r > 42.0) & (b - g > 18.0)
    score_blue = b - 0.65 * r - 0.25 * g
    mask_pink = valid & (r > 182.0) & (b > 152.0) & (g > 85.0) & (b - g > 20.0) & (r - g > 28.0)
    score_pink = 0.5 * (r + b) - 0.5 * g + (b - g)
    known = mask_white | mask_red | mask_yellow | mask_blue | mask_pink
    mask_other = valid & ~known & (vmax > 135.0) & (g > 130.0) & (g - r > 25.0)
    score_other = g - 0.6 * r
    return [('white', mask_white, score_white), ('red', mask_red, score_red), ('yellow', mask_yellow, score_yellow), ('blue', mask_blue, score_blue), ('pink', mask_pink, score_pink), ('other', mask_other, score_other)]

def _extract_merged_components(mask, color_score, gripper_mask, sx, sy):
    """Extract connected components and merge same-color fragments split by gripper fingers."""
    structure = np.ones((3, 3), dtype=bool)
    lbl, num = ndimage.label(mask, structure=structure)
    if num == 0:
        return []
    scale_area = sx * sy
    min_frag_area = max(6, int(round(8 * scale_area)))
    frags = []
    slices = ndimage.find_objects(lbl)
    for idx, slc in enumerate(slices, start=1):
        if slc is None:
            continue
        sub = lbl[slc] == idx
        area = int(np.count_nonzero(sub))
        if area < min_frag_area:
            continue
        ys, xs = np.nonzero(sub)
        ys_g = ys + slc[0].start
        xs_g = xs + slc[1].start
        frags.append({'ys': ys_g, 'xs': xs_g, 'area': area, 'cx': float(np.mean(xs_g)), 'cy': float(np.mean(ys_g)), 'x0': int(np.min(xs_g)), 'x1': int(np.max(xs_g)), 'y0': int(np.min(ys_g)), 'y1': int(np.max(ys_g))})
    if not frags:
        return []
    n = len(frags)
    parent = list(range(n))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i
    max_dist = 27.5 * math.hypot(sx, sy) / math.sqrt(2.0)
    max_box_gap = 16.0 * sx
    for i in range(n):
        for j in range(i + 1, n):
            fi, fj = (frags[i], frags[j])
            dist = math.hypot(fi['cx'] - fj['cx'], fi['cy'] - fj['cy'])
            gap_x = max(0, max(fi['x0'], fj['x0']) - min(fi['x1'], fj['x1']))
            gap_y = max(0, max(fi['y0'], fj['y0']) - min(fi['y1'], fj['y1']))
            if dist <= max_dist and gap_x <= max_box_gap and (gap_y <= max_box_gap):
                ya = max(0, min(fi['y0'], fj['y0']) - 1)
                yb = min(mask.shape[0], max(fi['y1'], fj['y1']) + 2)
                xa = max(0, min(fi['x0'], fj['x0']) - 1)
                xb = min(mask.shape[1], max(fi['x1'], fj['x1']) + 2)
                has_gripper = bool(np.any(gripper_mask[ya:yb, xa:xb]))
                if has_gripper or (gap_x <= 4 and gap_y <= 4):
                    ri, rj = (find(i), find(j))
                    if ri != rj:
                        parent[rj] = ri
    groups = {}
    for i in range(n):
        r_idx = find(i)
        groups.setdefault(r_idx, []).append(frags[i])
    components = []
    for grp in groups.values():
        ys = np.concatenate([f['ys'] for f in grp])
        xs = np.concatenate([f['xs'] for f in grp])
        area = int(ys.size)
        pix_scores = color_score[ys, xs]
        if float(np.percentile(pix_scores, 80)) < 55.0:
            continue
        x0, x1 = (int(np.min(xs)), int(np.max(xs)))
        y0, y1 = (int(np.min(ys)), int(np.max(ys)))
        if x1 - x0 + 1 > int(round(36 * sx)):
            continue
        components.append({'ys': ys, 'xs': xs, 'area': area, 'x0': x0, 'x1': x1, 'y0': y0, 'y1': y1, 'num_frags': len(grp)})
    return components

def _analyze_candidate(comp, color_name, color_score, img, gripper_mask, cx_cam, sx, sy):
    """Compute nut-vs-bolt classification score and 3D root center estimate."""
    ys = comp['ys']
    xs = comp['xs']
    x0, x1 = (comp['x0'], comp['x1'])
    y0, y1 = (comp['y0'], comp['y1'])
    area = comp['area']
    h, w = img.shape[:2]
    pad = 2
    by0 = max(0, y0 - pad)
    by1 = min(h, y1 + pad + 1)
    bx0 = max(0, x0 - pad)
    bx1 = min(w, x1 + pad + 1)
    sub_m = np.zeros((by1 - by0, bx1 - bx0), dtype=bool)
    sub_m[ys - by0, xs - bx0] = True
    sub_grip = gripper_mask[by0:by1, bx0:bx1]
    sub_score = color_score[by0:by1, bx0:bx1]
    sub_rgb = img[by0:by1, bx0:bx1]
    dil_grip = ndimage.binary_dilation(sub_grip, iterations=2)
    touches_gripper = bool(np.any(sub_m & dil_grip))
    grip_on_left = False
    grip_on_right = False
    grip_on_bottom = False
    if touches_gripper:
        gy, gx = np.nonzero(sub_grip)
        mx_mean = float(np.mean(xs - bx0))
        my_mean = float(np.mean(ys - by0))
        if gx.size > 0:
            if float(np.mean(gx)) < mx_mean:
                grip_on_left = True
            else:
                grip_on_right = True
            if float(np.mean(gy)) > my_mean:
                grip_on_bottom = True
    filled = ndimage.binary_fill_holes(sub_m)
    topo_hole = filled & ~sub_m & ~sub_grip
    topo_hole_area = int(np.count_nonzero(topo_hole))
    c_left = np.maximum.accumulate(sub_m, axis=1)
    c_right = np.maximum.accumulate(sub_m[:, ::-1], axis=1)[:, ::-1]
    c_up = np.maximum.accumulate(sub_m, axis=0)
    c_down = np.maximum.accumulate(sub_m[::-1, :], axis=0)[::-1]
    enclosed_4way = c_left & c_right & c_up & c_down & ~sub_grip
    enclosed_hole = enclosed_4way & ~sub_m
    enclosed_hole_area = int(np.count_nonzero(enclosed_hole))
    box_cx = 0.5 * float(x0 - bx0 + (x1 - bx0))
    box_cy = 0.5 * float(y0 - by0 + (y1 - by0))
    s_yy, s_xx = np.indices(sub_m.shape)
    dist_center = np.hypot(s_xx - box_cx, s_yy - box_cy)
    rim_pix = sub_m & (dist_center >= 3.0 * sx)
    if np.any(rim_pix):
        rim_val = float(np.percentile(sub_score[rim_pix], 75))
    else:
        rim_val = float(np.percentile(sub_score[sub_m], 75))
    center_win = (dist_center <= 2.8 * sx) & ~sub_grip
    if np.any(center_win):
        center_min = float(np.min(sub_score[center_win]))
        center_mean = float(np.mean(sub_score[center_win]))
        c_rgb = sub_rgb[center_win]
        wood_like = np.any((c_rgb[:, 0] > c_rgb[:, 1] + 15.0) & (c_rgb[:, 1] > c_rgb[:, 2] + 10.0) & (c_rgb[:, 2] < 105.0))
    else:
        center_min = rim_val
        center_mean = rim_val
        wood_like = False
    center_drop = max(0.0, (rim_val - center_min) / max(abs(rim_val), 40.0))
    center_mean_drop = max(0.0, (rim_val - center_mean) / max(abs(rim_val), 40.0))
    norm_area = float(area) / (sx * sy)
    bw = float(x1 - x0 + 1) / sx
    bh = float(y1 - y0 + 1) / sy
    row_widths = np.sum(sub_m, axis=1)
    active_rows = row_widths[row_widths > 0]
    if active_rows.size >= 6:
        k_top = max(2, int(0.35 * active_rows.size))
        k_bot = max(2, int(0.45 * active_rows.size))
        top_w = float(np.mean(active_rows[:k_top]))
        bot_w = float(np.mean(active_rows[-k_bot:]))
        taper_ratio = bot_w / max(top_w, 1.0)
    else:
        taper_ratio = 1.0
    hole_cue = 0.35 * min(float(topo_hole_area), 16.0) + 0.25 * min(float(enclosed_hole_area), 16.0) + 3.8 * center_drop + 2.2 * center_mean_drop + (1.2 if wood_like and center_drop > 0.32 else 0.0)
    bolt_cue = max(0.0, (norm_area - 195.0) / 32.0) + max(0.0, (bh - 18.5) * 0.42) + max(0.0, (taper_ratio - 1.18) * 2.2)
    if comp['num_frags'] > 1:
        bolt_cue += 1.2
    nut_score = hole_cue - bolt_cue - 1.35
    return {'comp': comp, 'color': color_name, 'nut_score': float(nut_score), 'hole_cue': float(hole_cue), 'bolt_cue': float(bolt_cue), 'touches_gripper': touches_gripper, 'grip_on_left': grip_on_left, 'grip_on_right': grip_on_right, 'grip_on_bottom': grip_on_bottom, 'filled_sub': filled, 'sub_grip': sub_grip, 'by0': by0, 'bx0': bx0, 'bw': bw, 'bh': bh, 'norm_area': norm_area, 'cx_cam': cx_cam, 'sx': sx, 'sy': sy}

def _estimate_root_xy(cand, kind):
    """Estimate projected 3D root center [x, y] from visible mask and object kind."""
    comp = cand['comp']
    ys = comp['ys'].astype(np.float64)
    xs = comp['xs'].astype(np.float64)
    x0, x1 = (float(comp['x0']), float(comp['x1']))
    y0, y1 = (float(comp['y0']), float(comp['y1']))
    sx, sy = (cand['sx'], cand['sy'])
    cx_cam = cand['cx_cam']
    if kind == 'nut':
        filled = cand['filled_sub'] & ~cand['sub_grip']
        f_ys, f_xs = np.nonzero(filled)
        if f_ys.size > 0:
            cx_vis = float(np.mean(f_xs)) + float(cand['bx0'])
            cy_vis = float(np.mean(f_ys)) + float(cand['by0'])
        else:
            cx_vis = float(np.mean(xs))
            cy_vis = float(np.mean(ys))
        root_x = cx_vis - 0.006 * (cx_vis - cx_cam)
        root_y = cy_vis + 0.55 * sy
        return [float(root_x), float(root_y)]
    if comp['num_frags'] > 1:
        cx_vis = float(np.mean(xs))
        cy_vis = float(np.mean(ys))
        return [float(cx_vis), float(cy_vis + 1.15 * sy)]
    span_y = max(1.0, y1 - y0)
    base_cut_y = y0 + 0.35 * span_y
    base_mask = ys >= base_cut_y
    if np.count_nonzero(base_mask) >= 10:
        bx_mean = float(np.mean(xs[base_mask]))
        by_mean = float(np.mean(ys[base_mask]))
    else:
        bx_mean = float(np.mean(xs))
        by_mean = float(np.mean(ys)) + 2.8 * sy
    whole_cx = float(np.mean(xs))
    whole_cy = float(np.mean(ys))
    root_x = 0.65 * bx_mean + 0.35 * whole_cx - 0.014 * (whole_cx - cx_cam)
    root_y = 0.55 * by_mean + 0.45 * (whole_cy + 3.6 * sy)
    return [float(root_x), float(root_y)]

def estimate_targets(rgb, camera_meta):
    """Estimate coarse 2D root pixel locations and classes ('nut' or 'bolt') from cam_head RGB."""
    if rgb is None:
        return {'objects': [], 'notes': 'Abstaining: rgb input is None.'}
    img = np.asarray(rgb, dtype=np.float32)
    if img.ndim != 3 or img.shape[2] < 3 or img.shape[0] < 64 or (img.shape[1] < 64):
        return {'objects': [], 'notes': 'Abstaining: invalid RGB shape.'}
    img = img[:, :, :3]
    if not np.all(np.isfinite(img)):
        img = np.nan_to_num(img, nan=0.0, posinf=255.0, neginf=0.0)
    if float(np.max(img)) <= 1.05:
        img = img * 255.0
    h, w = img.shape[:2]
    sx = float(w) / REF_WIDTH
    sy = float(h) / REF_HEIGHT
    _, _, cx_cam, _ = _extract_intrinsics(camera_meta, w, h)
    sample_patch = img[int(round(170 * sy)):int(round(210 * sy)), int(round(180 * sx)):int(round(460 * sx))]
    if sample_patch.size == 0:
        return {'objects': [], 'notes': 'Abstaining: empty tabletop reference region.'}
    med_r = float(np.median(sample_patch[:, :, 0]))
    med_g = float(np.median(sample_patch[:, :, 1]))
    med_b = float(np.median(sample_patch[:, :, 2]))
    if not (med_r > med_g > med_b and 75.0 <= med_r <= 220.0):
        return {'objects': [], 'notes': 'Abstaining: tabletop background appearance out of expected domain.'}
    roi, gripper_mask = _build_workspace_and_gripper_masks(img)
    channels = _compute_color_channels(img, roi, gripper_mask)
    candidates = []
    for color_name, mask_c, score_c in channels:
        comps = _extract_merged_components(mask_c, score_c, gripper_mask, sx, sy)
        for comp in comps:
            cand = _analyze_candidate(comp, color_name, score_c, img, gripper_mask, cx_cam, sx, sy)
            candidates.append(cand)
    candidates = [c for c in candidates if not (c['color'] == 'white' and c['touches_gripper'] and (c['bh'] > 1.5 * c['bw']) and (c['norm_area'] < 200))]
    suppressed = set()
    for i, a in enumerate(candidates):
        for j, b in enumerate(candidates):
            if i == j or a['color'] != 'white' or b['color'] in ('white', 'other'):
                continue
            aa, bb = (a['comp'], b['comp'])
            iw = max(0, min(aa['x1'], bb['x1']) - max(aa['x0'], bb['x0']) + 1)
            ih = max(0, min(aa['y1'], bb['y1']) - max(aa['y0'], bb['y0']) + 1)
            area_a = (aa['x1'] - aa['x0'] + 1) * (aa['y1'] - aa['y0'] + 1)
            area_b = (bb['x1'] - bb['x0'] + 1) * (bb['y1'] - bb['y0'] + 1)
            if iw * ih / max(1, min(area_a, area_b)) > 0.65:
                suppressed.add(i)
    candidates = [c for i, c in enumerate(candidates) if i not in suppressed]
    if not candidates:
        return {'objects': [], 'notes': 'Abstaining: no high-confidence nut or bolt candidates found.'}
    by_color = {}
    for idx, cand in enumerate(candidates):
        by_color.setdefault(cand['color'], []).append(idx)
    decisions = {}
    for color_name, idxs in by_color.items():
        if len(idxs) == 2 and color_name != 'other':
            i0, i1 = (idxs[0], idxs[1])
            s0 = candidates[i0]['nut_score']
            s1 = candidates[i1]['nut_score']
            margin = abs(s0 - s1)
            if s0 >= s1:
                decisions[i0] = ('nut', max(abs(s0), 0.5 * margin + 0.8))
                decisions[i1] = ('bolt', max(abs(s1), 0.5 * margin + 0.8))
            else:
                decisions[i1] = ('nut', max(abs(s1), 0.5 * margin + 0.8))
                decisions[i0] = ('bolt', max(abs(s0), 0.5 * margin + 0.8))
        else:
            for idx in idxs:
                s = candidates[idx]['nut_score']
                kind = 'nut' if s >= 0.0 else 'bolt'
                decisions[idx] = (kind, abs(s))
    objects = []
    occluded_count = 0
    for idx, cand in enumerate(candidates):
        kind, margin = decisions[idx]
        pixel_xy = _estimate_root_xy(cand, kind)
        base_conf = 0.62 + 0.34 * (1.0 - math.exp(-0.55 * float(margin)))
        if cand['touches_gripper'] or cand['comp']['num_frags'] > 1:
            base_conf -= 0.08
            occluded_count += 1
        conf = float(min(0.98, max(0.0, base_conf)))
        objects.append({'kind': str(kind), 'color': str(cand['color']), 'pixel_xy': [float(pixel_xy[0]), float(pixel_xy[1])], 'confidence': round(conf, 4)})
    objects.sort(key=lambda d: (-d['confidence'], d['kind'], d['pixel_xy'][0]))
    num_nuts = sum((1 for o in objects if o['kind'] == 'nut'))
    num_bolts = sum((1 for o in objects if o['kind'] == 'bolt'))
    notes = f'Detected {len(objects)} objects ({num_nuts} nuts, {num_bolts} bolts; {occluded_count} partially occluded by gripper fingers). Coarse cam_head root estimates compensate for bolt shaft perspective and finger occlusion; close-range wrist camera views should refine submillimeter alignment before insertion.'
    return {'objects': objects, 'notes': notes}

def _unit(vec):
    v = np.asarray(vec, dtype=float).reshape(-1)
    norm = float(np.linalg.norm(v))
    if norm < 1e-09:
        return np.zeros_like(v)
    return v / norm

def _rotation(quat_wxyz):
    """Convert a wxyz quaternion to a 3x3 rotation matrix."""
    q = np.asarray(quat_wxyz, dtype=float).reshape(4)
    norm = float(np.linalg.norm(q))
    if norm < 1e-09:
        return np.eye(3, dtype=float)
    w, x, y, z = q / norm
    return np.array([[1.0 - 2.0 * (y * y + z * z), 2.0 * (x * y - z * w), 2.0 * (x * z + y * w)], [2.0 * (x * y + z * w), 1.0 - 2.0 * (x * x + z * z), 2.0 * (y * z - x * w)], [2.0 * (x * z - y * w), 2.0 * (y * z + x * w), 1.0 - 2.0 * (x * x + y * y)]], dtype=float)

def _angles(rot_mat):
    """Convert a 3x3 end-effector rotation matrix to this library's pitch, yaw, roll (degrees)."""
    r = np.asarray(rot_mat, dtype=float).reshape(3, 3)
    pitch = math.degrees(math.asin(float(np.clip(-r[2, 0], -1.0, 1.0))))
    if math.hypot(float(r[0, 0]), float(r[1, 0])) < 1e-08:
        yaw = math.degrees(math.atan2(float(-r[1, 1]), float(-r[0, 1])))
        roll = 0.0
    else:
        yaw = math.degrees(math.atan2(float(r[1, 0]), float(r[0, 0]))) - 90.0
        roll = math.degrees(math.atan2(float(r[2, 1]), float(r[2, 2])))
    return {'pitch': float(pitch), 'yaw': float((yaw + 180.0) % 360.0 - 180.0), 'roll': float((roll + 180.0) % 360.0 - 180.0)}

def _camera_pose(arm_state, camera_meta, target, center):
    target = np.asarray(target, float)
    center = np.asarray(center, float)
    camera = np.asarray(camera_meta['extrinsic_matrix'], float)
    eef_rotation = _rotation(arm_state.eef_quat)
    camera_in_eef = eef_rotation.T @ camera[:3, :3]
    camera_offset = eef_rotation.T @ (camera[:3, 3] - np.asarray(arm_state.eef_pos))
    tcp_offset = eef_rotation.T @ (np.asarray(arm_state.tcp_pos) - np.asarray(arm_state.eef_pos))
    z = _unit(center - target)
    x = _unit(np.cross(np.array([0.0, 0.0, 1.0]), z))
    y = np.cross(z, x)
    desired_eef = np.column_stack((x, y, z)) @ camera_in_eef.T
    eef_position = center - desired_eef @ camera_offset
    return {'xyz': (eef_position + desired_eef @ tcp_offset).tolist(), **_angles(desired_eef)}

def _coarse_bolt_target(rgb, meta):
    objects = estimate_targets(rgb, meta)['objects']
    bolts = [o for o in objects if o['kind'] == 'bolt']
    if not bolts:
        raise RuntimeError('No bolt detection')
    bolt = max(bolts, key=lambda o: o['pixel_xy'][0])
    x, y = bolt['pixel_xy']
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    ray = np.linalg.solve(K, [x, y, 1.0]) * [1, -1, -1]
    direction = T[:3, :3] @ ray
    depth = (0.765 - T[2, 3]) / direction[2]
    if depth <= 0:
        raise RuntimeError('Invalid table intersection')
    root = T[:3, 3] + depth * direction
    if not -0.46 < root[0] < 0.46 or not -0.32 < root[1] < 0.08:
        raise RuntimeError('Bolt outside expected workspace')
    return (root, bolt)
import numpy as np
from scipy.ndimage import label

def rotation(q):
    w, x, y, z = np.asarray(q, float) / np.linalg.norm(q)
    return np.array([[1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w)], [2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w)], [2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y)]])

def checked(robo, xyz, arm, pitch, yaw, roll, gripper):
    preview = robo.preview_move(list(xyz), arm=arm, pitch=pitch, yaw=yaw, roll=roll, path='line')
    if not preview.get('reachable') or preview.get('ik_error') or preview.get('note'):
        raise RuntimeError('Bounded path rejected ' + str(preview))
    rec = robo.move_to(list(xyz), arm=arm, pitch=pitch, yaw=yaw, roll=roll, gripper=gripper, path='line')
    if not rec.reached or rec.blocked or rec.ik_error:
        raise RuntimeError('Bounded move stopped ' + str(rec))
    return rec

def world_targets(robo):
    meta = robo.camera_meta('cam_head')
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    objects = estimate_targets(robo.image('cam_head'), meta)['objects']
    for o in objects:
        x, y = o['pixel_xy']
        ray = np.linalg.solve(K, [x, y, 1.0]) * [1, -1, -1]
        d = T[:3, :3] @ ray
        z = NUT_ROOT_Z if o['kind'] == 'nut' else 0.765
        o['world_root'] = (T[:3, 3] + d * (z - T[2, 3]) / d[2]).tolist()
    return objects

import numpy as np
from scipy.ndimage import label
from scipy.spatial import ConvexHull
from scipy.optimize import least_squares

# RGB-derived medians; per-color uncertainty and supporting views:
# docs/fasten_screws/applied_values.json (rgb_derived_values).
RGB_BOLT_GEOMETRY = {'blue': {'cap_z': 0.81615, 'height': 0.05085}, 'pink': {'cap_z': 0.8167, 'height': 0.05155}, 'red': {'cap_z': 0.81695, 'height': 0.05165}, 'white': {'cap_z': 0.8177, 'height': 0.0517}, 'yellow': {'cap_z': 0.8158, 'height': 0.0507}}
# Visible lower/upper nut planes from quantization RGB estimates.
# See the same evidence file for sample spreads and uncertainty envelopes.
RGB_NUT_GEOMETRY = {'blue': {'face_z': (0.76545, 0.7841), 'radius': 0.02049}, 'pink': {'face_z': (0.76605, 0.78405), 'radius': 0.02032}, 'red': {'face_z': (0.766, 0.7838), 'radius': 0.02051}, 'white': {'face_z': (0.7661, 0.785), 'radius': 0.02045}, 'yellow': {'face_z': (0.76565, 0.78385), 'radius': 0.02049}}
# Nut reference height: midpoint of the RGB-fitted lower/upper faces, median over colours.
NUT_ROOT_Z = float(np.median([sum(g['face_z']) / 2.0 for g in RGB_NUT_GEOMETRY.values()]))
# Fallback face heights for a colour without its own RGB fit: per-face median over the fitted colours.
NUT_FACE_Z_FALLBACK = tuple(float(np.median([g['face_z'][i] for g in RGB_NUT_GEOMETRY.values()])) for i in (0, 1))
NUT_RING_RADIUS_DEFAULT = 0.02049


def _fit_flat_hex(project, observed, coarse, half_window, color='blue'):
    """Fit a flat hexagonal nut to an observed silhouette in one calibrated view.

    project: maps (N, 3) world points to (N, 2) pixel coordinates.
    observed: (M, 2) convex-hull vertices of the nut's colour component (pixels).
    coarse: approximate world root; the fit searches +/- half_window metres in x and y.
    The model is two hexagonal corner rings at RGB-fitted lower/upper face
    heights, separately from NUT_ROOT_Z. Free parameters: x, y, yaw (degrees) and the corner-ring
    radius (metres). If the fitted radius lands at its search limit the radius is
    treated as unavailable and the fit is repeated with that color's RGB radius.
    Returns (x, y, yaw_deg, radius_m, radius_measured, pixel_rms).
    """
    angles = np.radians(30 + 60 * np.arange(6))
    unit_ring = np.c_[np.cos(angles), np.sin(angles)]
    shape_geometry = RGB_NUT_GEOMETRY.get(color, {
        'face_z': NUT_FACE_Z_FALLBACK, 'radius': 0.02028,
    })
    radius_initial = shape_geometry['radius']

    def residual(params, radius=None):
        x, y, yaw = params[:3]
        rad = params[3] if radius is None else radius
        shape = np.vstack([np.c_[rad * unit_ring, np.full(6, z - NUT_ROOT_Z)]
                           for z in shape_geometry['face_z']])
        theta = np.radians(yaw)
        R = np.array([[np.cos(theta), -np.sin(theta), 0.0], [np.sin(theta), np.cos(theta), 0.0], [0.0, 0.0, 1.0]])
        v = project(shape @ R.T + [x, y, NUT_ROOT_Z])
        poly = v[ConvexHull(v).vertices]
        edge = np.roll(poly, -1, axis=0) - poly
        delta = observed[:, None, :] - poly[None, :, :]
        fraction = np.clip(np.sum(delta * edge, axis=2) / np.sum(edge * edge, axis=1), 0.0, 1.0)
        dist = np.linalg.norm(delta - fraction[:, :, None] * edge, axis=2)
        return dist.min(axis=1)
    lo = [coarse[0] - half_window, coarse[1] - half_window, -180.0]
    hi = [coarse[0] + half_window, coarse[1] + half_window, 180.0]
    radius_lo = 0.5 * radius_initial
    radius_hi = 2.0 * radius_initial
    fits = [least_squares(residual, [coarse[0], coarse[1], yaw, radius_initial], bounds=(lo + [radius_lo], hi + [radius_hi]), max_nfev=200) for yaw in range(0, 60, 10)]
    fit = min(fits, key=lambda f: np.mean(residual(f.x) ** 2))
    radius = float(fit.x[3])
    measured = radius_lo < radius < radius_hi
    if measured:
        params, rms = fit.x[:3], float(np.sqrt(np.mean(residual(fit.x) ** 2)))
    else:
        radius = radius_initial
        fits = [least_squares(lambda q: residual(q, radius), [coarse[0], coarse[1], yaw], bounds=(lo, hi), max_nfev=150) for yaw in range(0, 60, 10)]
        fit = min(fits, key=lambda f: np.mean(residual(f.x, radius) ** 2))
        params, rms = fit.x, float(np.sqrt(np.mean(residual(fit.x, radius) ** 2)))
    return float(params[0]), float(params[1]), float(params[2]), radius, measured, rms

def detect(rgb, meta, coarse):
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    a = np.asarray(rgb, float)
    r, g, b = a.transpose(2, 0, 1)

    def project(xyz):
        q = (np.asarray(xyz) - T[:3, 3]) @ T[:3, :3]
        return np.column_stack((K[0, 0] * q[:, 0] / -q[:, 2] + K[0, 2], K[1, 1] * q[:, 1] / q[:, 2] + K[1, 2]))
    xy = project([coarse])[0]
    yy, xx = np.indices(r.shape)
    mask = (b > 150) & (b - r > 40) & (b - g > 40) & (abs(xx - xy[0]) < 60) & (abs(yy - xy[1]) < 60)
    ll, n = label(mask)
    parts = [np.argwhere(ll == i) for i in range(1, n + 1)]
    parts = [v for v in parts if len(v) > 40 and np.linalg.norm(v[:, ::-1].mean(axis=0) - xy) < 20]
    if len(parts) != 1:
        raise RuntimeError('No unique blue nut component')
    pixels = parts[0][:, ::-1]
    observed = pixels[ConvexHull(pixels).vertices].astype(float)
    x, y, yaw, radius, radius_measured, rms = _fit_flat_hex(project, observed, coarse, 0.012)
    if rms > 1.5:
        raise RuntimeError('Hex silhouette fit residual too large')
    return {'root': [x, y, NUT_ROOT_Z], 'flat_yaw_deg': float((yaw + 30) % 60 - 30), 'pixel_rms': rms, 'pixels': len(pixels), 'ring_radius_m': radius, 'ring_radius_measured': radius_measured, 'scope': 'Flat table nut only; compact static hex prior, no held-pose claim'}

def detect_bolt_cap(rgb, meta, coarse):
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    top = np.asarray(coarse) + [0, 0, RGB_BOLT_GEOMETRY['blue']['height']]
    q = T[:3, :3].T @ (top - T[:3, 3])
    pixel = np.array([K[1, 1] * q[1] / q[2] + K[1, 2], K[0, 0] * q[0] / -q[2] + K[0, 2]])
    a = np.asarray(rgb, float)
    r, g, b = a.transpose(2, 0, 1)
    yy, xx = np.indices(r.shape)
    mask = (b > 200) & (b - r > 50) & (b - g > 50) & (abs(yy - pixel[0]) < 35) & (abs(xx - pixel[1]) < 35)
    rc = np.argwhere(mask)
    if len(rc) < 300:
        raise RuntimeError('Insufficient blue silhouette')
    upper = []
    for col in np.unique(rc[:, 1]):
        row = rc[rc[:, 1] == col, 0].min()
        if row <= rc[:, 0].min() + 14:
            upper.append([row, col])
    pts = []
    for row, col in upper:
        ray = np.linalg.solve(K, [col, row, 1.0]) * [1, -1, -1]
        d = T[:3, :3] @ ray
        t = (RGB_BOLT_GEOMETRY['blue']['cap_z'] - T[2, 3]) / d[2]
        pts.append((T[:3, 3] + t * d)[:2])
    pts = np.asarray(pts)
    if len(pts) < 20:
        raise RuntimeError('Too little upper rim')
    radius = 0.01
    fit = least_squares(lambda center: np.linalg.norm(pts - center, axis=1) - radius, np.asarray(coarse)[:2], loss='soft_l1', f_scale=0.0003)
    center = fit.x
    resid = float(np.median(abs(np.linalg.norm(pts - center, axis=1) - radius)))
    if resid > 0.0005 or np.linalg.norm(center - np.asarray(coarse)[:2]) > 0.005:
        raise RuntimeError('Upper arc geometry disagrees')
    return {'root': [float(center[0]), float(center[1]), 0.765], 'arc_pixels': len(pts), 'median_radius_residual_m': resid, 'radius_prior_m': radius}

def acquire_blue_target(robo):
    objects = world_targets(robo)
    matches = [o for o in objects if o['kind'] == 'bolt' and o['color'] == 'blue']
    if len(matches) != 1:
        raise RuntimeError('No unique blue bolt')
    root = np.asarray(matches[0]['world_root'])
    arm = 'left' if root[0] > 0 else 'right'
    sign = -1.0 if arm == 'left' else 1.0
    target = root + [0.0, 0.0, 0.02]
    close = robo.set_gripper(arm, robo.CLOSE)
    if close.holding or float(close.opening) > 0.02:
        raise RuntimeError('Observer not empty')
    positions = []
    for index, y in enumerate([-0.02, 0.04]):
        if index:
            home = robo.home(arm)
            if not home.reached:
                raise RuntimeError('Observer home failed before second view')
        offsets = [np.array([sign * 0.1, y, 0.2])]
        if index:
            offsets.extend([np.array([sign * 0.12, y, 0.2]), np.array([sign * 0.1, 0.02, 0.2])])
        pose = None
        for offset in offsets:
            proposed = _camera_pose(robo.state().arm(arm), robo.camera_meta('cam_' + arm + '_wrist'), target, target + offset)
            preview = robo.preview_move(proposed['xyz'], arm=arm, pitch=proposed['pitch'], yaw=proposed['yaw'], roll=proposed['roll'], path='line')
            if preview.get('reachable') and (not preview.get('ik_error')) and (not preview.get('note')):
                pose = proposed
                break
        if pose is None:
            raise RuntimeError('No exact bounded second cap camera pose')
        reply = checked(robo, pose['xyz'], arm, pose['pitch'], pose['yaw'], pose['roll'], robo.CLOSE)
        rgb = robo.image('cam_' + arm + '_wrist')
        pred = detect_bolt_cap(rgb, robo.camera_meta('cam_' + arm + '_wrist'), root)
        positions.append(pred['root'])
        print({'pregrasp_cap_fit': pred})
        print({'blue_cap_camera': True, 'arm': arm, 'coarse_root': root.tolist(), 'offset': offset.tolist(), 'reply': str(reply)})
    h = robo.home('both')
    if not h.reached:
        raise RuntimeError('Empty arms failed home before grasp')
    disagreement = float(np.linalg.norm(np.asarray(positions[0]) - positions[1]))
    if disagreement > 0.0015:
        raise RuntimeError('Cap views disagree')
    return {'root': np.mean(positions, axis=0).tolist(), 'view_disagreement_m': disagreement}

def detect_pink_bolt_cap(rgb, meta, coarse):
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    top = np.asarray(coarse) + [0, 0, RGB_BOLT_GEOMETRY['pink']['height']]
    q = T[:3, :3].T @ (top - T[:3, 3])
    pixel = np.array([K[1, 1] * q[1] / q[2] + K[1, 2], K[0, 0] * q[0] / -q[2] + K[0, 2]])
    a = np.asarray(rgb, dtype=float)
    r, g, b = a.transpose(2, 0, 1)
    yy, xx = np.indices(r.shape)
    roi = (abs(yy - pixel[0]) < 35) & (abs(xx - pixel[1]) < 35)
    pink = (r > 210) & (b > 220) & (r - g > 8) & (b - g > 10) & roi
    if pink.sum() < 100:
        raise RuntimeError('Insufficient visible pink cap')
    cutoff = float(np.percentile(g[pink], 95) - 2)
    mask = pink & (g > cutoff)
    ll, n = label(mask)
    candidates = []
    for i in range(1, n + 1):
        rc = np.argwhere(ll == i)
        if len(rc) < 150:
            continue
        center = rc.mean(axis=0)
        span = rc.max(axis=0) - rc.min(axis=0) + 1
        if np.min(span) < 12 or max(span) / min(span) > 1.8 or np.linalg.norm(center - pixel) > 18:
            continue
        candidates.append((len(rc), center))
    if len(candidates) != 1:
        raise RuntimeError('Ambiguous cap segmentation')
    area, center = candidates[0]
    ray = np.linalg.solve(K, [center[1], center[0], 1.0]) * [1, -1, -1]
    direction = T[:3, :3] @ ray
    distance = (RGB_BOLT_GEOMETRY['pink']['cap_z'] - T[2, 3]) / direction[2]
    if distance <= 0:
        raise RuntimeError('Invalid cap ray')
    pos = T[:3, 3] + distance * direction
    pos[2] = 0.765
    return {'root': pos.tolist(), 'cap_pixel_rc': center.tolist(), 'predicted_cap_rc': pixel.tolist(), 'area': area, 'brightness_cutoff': cutoff}

