def acquire_pink_grasp(robo):
    objects = world_targets(robo)
    matches = [x for x in objects if x['kind'] == 'nut' and x['color'] == 'pink']
    if len(matches) != 1:
        raise RuntimeError('No unique pink nut')
    root = np.asarray(matches[0]['world_root'])
    arm = 'left' if root[0] < 0 else 'right'
    close = robo.set_gripper(arm, robo.CLOSE)
    if close.holding or float(close.opening) > 0.02:
        raise RuntimeError('Observer not empty')
    target = root + [0.0, 0.0, 0.01]
    fits = []
    for i, x in enumerate([0.0, 0.03]):
        offset = np.array([x, -0.08, 0.2])
        pose = _camera_pose(robo.state().arm(arm), robo.camera_meta('cam_' + arm + '_wrist'), target, target + offset)
        rec = checked(robo, pose['xyz'], arm, pose['pitch'], pose['yaw'], pose['roll'], robo.CLOSE)
        rgb = robo.image('cam_' + arm + '_wrist')
        print({'pink_nut_camera': i, 'coarse': root.tolist(), 'pose': pose, 'reply': str(rec)})
        fit = detect_pink_flat_nut(rgb, robo.camera_meta('cam_' + arm + '_wrist'), root)
        fits.append(fit)
        print({'pink_nut_fit': fit})
    disagreement = float(np.linalg.norm(np.asarray(fits[0]['root']) - np.asarray(fits[1]['root'])))
    yawdiff = abs((fits[0]['flat_yaw_deg'] - fits[1]['flat_yaw_deg'] + 30) % 60 - 30)
    if disagreement > 0.002 or yawdiff > 5:
        raise RuntimeError('Nut camera fits disagree')
    point = np.mean([f['root'] for f in fits], axis=0)
    angles = np.radians([f['flat_yaw_deg'] * 6 for f in fits])
    yaw = float(np.degrees(np.arctan2(np.sin(angles).mean(), np.cos(angles).mean())) / 6)
    opened = robo.set_gripper(arm, robo.OPEN)
    print({'empty_observer_open': str(opened)})
    for z in [0.85, float(point[2] + 0.007)]:
        rec = checked(robo, [float(point[0]), float(point[1]), z], arm, 90.0, yaw, 0.0, robo.OPEN)
        if abs((float(rec.roll) + 180) % 360 - 180) > 5:
            raise RuntimeError('Alternate roll unsupported')
    close = robo.set_gripper(arm, robo.CLOSE)
    print({'pink_nut_close': str(close)})
    if not close.holding or close.width_m is None or (not 0.025 < close.width_m < 0.045):
        raise RuntimeError('No supported nut grip')
    closure = robo.state().arm(arm)
    held_offset = rotation(closure.eef_quat).T @ (point - np.asarray(closure.tcp_pos))
    print({'closure_held_offset_eef': held_offset.tolist(), 'source': 'observed flat root and actual closure proprioception'})
    rec = checked(robo, [float(point[0]), float(point[1]), 0.87], arm, 90.0, 0.0, 0.0, robo.CLOSE)
    robo.image('cam_head')
    print({'pink_nut_lift': str(rec), 'fitted_root': point.tolist()})
    return {'arm': arm, 'held_offset_eef': held_offset.tolist(), 'observed_pregrasp_root': point.tolist()}

def blue_acquire_first(robo):
    bolt = np.asarray(acquire_blue_target(robo)['root'])
    receiver = 'left' if bolt[0] < 0 else 'right'
    print({'bolt_side_receiver': receiver, 'bolt': bolt.tolist()})
    grasp = relay_and_regrasp(robo, receiver)
    arm = grasp['arm']
    held_offset = grasp['held_offset_eef']
    checked(robo, [float(bolt[0]), float(bolt[1]), 0.87], arm, 90.0, 150.0, 0.0, robo.CLOSE)
    offset = rotation(robo.state().arm(arm).eef_quat) @ np.asarray(held_offset)
    xy = bolt[:2] - offset[:2]
    for root_z in [0.8324, 0.8203, 0.812, 0.8048, 0.8025]:
        checked(robo, [float(xy[0]), float(xy[1]), float(root_z - offset[2])], arm, 90.0, 150.0, 0.0, robo.CLOSE)
        robo.image('cam_' + arm + '_wrist')
    for yaw, root_z in [(150.0, 0.8174), (0.0, 0.8144), (-150.0, 0.8114)]:
        checked(robo, [float(xy[0]), float(xy[1]), float(root_z - offset[2])], arm, 90.0, yaw, 0.0, robo.CLOSE)
        robo.image('cam_' + arm + '_wrist')
    return arm

def detect_red_bolt_cap(rgb, meta, coarse):
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    top = np.asarray(coarse) + [0, 0, RGB_BOLT_GEOMETRY['red']['height']]
    q = T[:3, :3].T @ (top - T[:3, 3])
    pixel = np.array([K[1, 1] * q[1] / q[2] + K[1, 2], K[0, 0] * q[0] / -q[2] + K[0, 2]])
    a = np.asarray(rgb, float)
    r, g, b = a.transpose(2, 0, 1)
    yy, xx = np.indices(r.shape)
    mask = (r > 200) & (r - g > 50) & (r - b > 50) & (abs(yy - pixel[0]) < 35) & (abs(xx - pixel[1]) < 35)
    rc = np.argwhere(mask)
    if len(rc) < 300:
        raise RuntimeError('Insufficient blue silhouette')
    upper = []
    for col in np.unique(rc[:, 1]):
        row = rc[rc[:, 1] == col, 0].min()
        if row <= rc[:, 0].min() + 14:
            upper.append([row, col])
    pts = []
    for row, col in upper:
        ray = np.linalg.solve(K, [col, row, 1.0]) * [1, -1, -1]
        d = T[:3, :3] @ ray
        t = (RGB_BOLT_GEOMETRY['red']['cap_z'] - T[2, 3]) / d[2]
        pts.append((T[:3, 3] + t * d)[:2])
    pts = np.asarray(pts)
    if len(pts) < 20:
        raise RuntimeError('Too little upper rim')
    radius = 0.01
    fit = least_squares(lambda center: np.linalg.norm(pts - center, axis=1) - radius, np.asarray(coarse)[:2], loss='soft_l1', f_scale=0.0003)
    center = fit.x
    resid = float(np.median(abs(np.linalg.norm(pts - center, axis=1) - radius)))
    if resid > 0.0005 or np.linalg.norm(center - np.asarray(coarse)[:2]) > 0.005:
        raise RuntimeError('Upper arc geometry disagrees')
    return {'root': [float(center[0]), float(center[1]), 0.765], 'arc_pixels': len(pts), 'median_radius_residual_m': resid, 'radius_prior_m': radius}

def red_acquire_first(robo):
    objects = world_targets(robo)
    matches = [x for x in objects if x['kind'] == 'nut' and x['color'] == 'red']
    if len(matches) != 1:
        raise RuntimeError('No unique red nut')
    root = np.asarray(matches[0]['world_root'])
    arm = 'left' if root[0] < 0 else 'right'
    close = robo.set_gripper(arm, robo.CLOSE)
    if close.holding or float(close.opening) > 0.02:
        raise RuntimeError('Observer not empty')
    bolts = [o for o in objects if o['kind'] == 'bolt' and o['color'] == 'red']
    if len(bolts) != 1:
        raise RuntimeError('No unique red bolt')
    bolt_root = np.asarray(bolts[0]['world_root'])
    caps = []
    target = root + [0.0, 0.0, 0.01]
    fits = []
    for i, x in enumerate([0.0, 0.03]):
        offset = np.array([x, -0.08, 0.2])
        pose = _camera_pose(robo.state().arm(arm), robo.camera_meta('cam_' + arm + '_wrist'), target, target + offset)
        rec = checked(robo, pose['xyz'], arm, pose['pitch'], pose['yaw'], pose['roll'], robo.CLOSE)
        rgb = robo.image('cam_' + arm + '_wrist')
        print({'red_nut_camera': i, 'coarse': root.tolist(), 'pose': pose, 'reply': str(rec)})
        fit = detect_red_flat_nut(rgb, robo.camera_meta('cam_' + arm + '_wrist'), root)
        fits.append(fit)
        print({'red_nut_fit': fit})
        cap = detect_red_bolt_cap(rgb, robo.camera_meta('cam_' + arm + '_wrist'), bolt_root)
        caps.append(cap)
        print({'cached_red_cap': cap})
    disagreement = float(np.linalg.norm(np.asarray(fits[0]['root']) - np.asarray(fits[1]['root'])))
    yawdiff = abs((fits[0]['flat_yaw_deg'] - fits[1]['flat_yaw_deg'] + 30) % 60 - 30)
    if disagreement > 0.002 or yawdiff > 5:
        raise RuntimeError('Nut camera fits disagree')
    point = np.mean([f['root'] for f in fits], axis=0)
    angles = np.radians([f['flat_yaw_deg'] * 6 for f in fits])
    yaw = float(np.degrees(np.arctan2(np.sin(angles).mean(), np.cos(angles).mean())) / 6)
    opened = robo.set_gripper(arm, robo.OPEN)
    print({'empty_observer_open': str(opened)})
    for z in [0.85, float(point[2] + 0.007)]:
        rec = checked(robo, [float(point[0]), float(point[1]), z], arm, 90.0, yaw, 0.0, robo.OPEN)
        if abs((float(rec.roll) + 180) % 360 - 180) > 5:
            raise RuntimeError('Alternate roll unsupported')
    close = robo.set_gripper(arm, robo.CLOSE)
    print({'red_nut_close': str(close)})
    if not close.holding or close.width_m is None or (not 0.025 < close.width_m < 0.045):
        raise RuntimeError('No supported nut grip')
    closure = robo.state().arm(arm)
    held_offset = rotation(closure.eef_quat).T @ (point - np.asarray(closure.tcp_pos))
    rec = checked(robo, [float(point[0]), float(point[1]), 0.87], arm, 90.0, 0.0, 0.0, robo.CLOSE)
    robo.image('cam_head')
    print({'red_nut_lift': str(rec), 'fitted_root': point.tolist()})
    bolt = np.mean([c['root'] for c in caps], axis=0)
    if np.linalg.norm(np.asarray(caps[0]['root']) - np.asarray(caps[1]['root'])) > 0.0015:
        raise RuntimeError('Cap views disagree')
    checked(robo, [float(bolt[0]), float(bolt[1]), 0.87], arm, 90.0, 150.0, 0.0, robo.CLOSE)
    offset = rotation(robo.state().arm(arm).eef_quat) @ np.asarray(held_offset)
    xy = bolt[:2] - offset[:2]
    for root_z in [0.8324, 0.8203, 0.812, 0.8048, 0.8025]:
        checked(robo, [float(xy[0]), float(xy[1]), float(root_z - offset[2])], arm, 90.0, 150.0, 0.0, robo.CLOSE)
        robo.image('cam_' + arm + '_wrist')
    for yaw, root_z in [(150.0, 0.8174), (0.0, 0.8144), (-150.0, 0.8114)]:
        checked(robo, [float(xy[0]), float(xy[1]), float(root_z - offset[2])], arm, 90.0, yaw, 0.0, robo.CLOSE)
        robo.image('cam_' + arm + '_wrist')
    return arm

def finish_pair(robo, arm, final_pair=False):
    initial = robo.state().arm(arm)
    if abs(initial.pitch - 90) > 2 or abs(initial.yaw + 150) > 2 or (not 0.812 < initial.tcp_pos[2] < 0.83) or (not 0.1 < initial.gripper < 0.65):
        raise RuntimeError('Outside supported firststroke phase')
    xy = np.asarray(initial.tcp_pos[:2])
    for stroke in range(3):
        state = robo.state().arm(arm)
        z_grasp = float(state.tcp_pos[2] + 0.003)
        print({'ratchet': stroke + 2, 'z_grasp': z_grasp, 'postcontact_root_prior_m': 0.002, 'uncertainty_m': 0.002})
        robo.set_gripper(arm, robo.OPEN, opening=0.65)
        goal = [float(xy[0]), float(xy[1]), z_grasp]
        preview = robo.preview_move(goal, arm=arm, pitch=90.0, yaw=150.0, roll=0.0, path='auto')
        if not preview.get('reachable') or preview.get('ik_error') or preview.get('note'):
            raise RuntimeError('Open-jaw joint reset exact preview rejected')
        sweep = max([float(np.linalg.norm(np.asarray(point)[:2] - xy)) for point in preview.get('tcp_waypoints', [])], default=100.0)
        if sweep > 0.001:
            raise RuntimeError('Open-jaw reset preview XY sweep exceeds1mm')
        print({'open_reset_preview': preview, 'max_xy_sweep_m': sweep})
        rec = robo.move_to(goal, arm=arm, pitch=90.0, yaw=150.0, roll=0.0, path='auto', gripper=robo.KEEP)
        print({'open_jaw_joint_reset': str(rec), 'closed_strokes_unchanged': True})
        if not rec.reached or rec.blocked or rec.ik_error or rec.truncated:
            raise RuntimeError('Open-jaw joint reset reply failed')
        st = robo.state().arm(arm)
        if np.linalg.norm(np.asarray(st.tcp_pos) - np.asarray(goal)) > 0.003 or abs(st.yaw - 150.0) > 2:
            raise RuntimeError('Open-jaw reset actual pose mismatch')
        close = robo.set_gripper(arm, robo.CLOSE)
        if not close.holding or close.width_m is None or (not 0.025 < close.width_m < 0.045):
            raise RuntimeError('No supported nut regrasp')
        for yaw, z in [(0.0, z_grasp - 0.0025), (-150.0, z_grasp - 0.0055)]:
            checked(robo, [float(xy[0]), float(xy[1]), z], arm, 90.0, yaw, 0.0, robo.CLOSE)
            robo.image('cam_' + arm + '_wrist')
    observer = 'right' if arm == 'left' else 'left'
    if final_pair:
        opening = float(robo.state().arm(observer).gripper)
        if 0.05 < opening < 0.95:
            raise RuntimeError('Unexpected retained object in completion observer')
        reply = robo.set_gripper(observer, robo.OPEN)
        print({'final_empty_observer_release': str(reply)})
        if float(reply.opening) < 0.95:
            raise RuntimeError('Observer release incomplete')
    reply = robo.set_gripper(arm, robo.OPEN)
    print({'pair_release': str(reply), 'final_pair': final_pair})
    if final_pair:
        return guarded_empty_home_both(robo)
    checked(robo, [float(xy[0]), float(xy[1]), 0.9], arm, 90.0, -150.0, 0.0, robo.OPEN)
    home = robo.home(arm)
    robo.image('cam_head')
    print({'pair_home': arm, 'reply': str(home)})
    if not home.reached:
        raise RuntimeError('Pair home stopped; the episode outcome decides success')
    if final_pair:
        home = robo.home(observer)
        print({'final_empty_observer_home': str(home)})
        if not home.reached and (not getattr(home, 'truncated', False)):
            raise RuntimeError('Final observer home did not reach')

def relay_and_regrasp(robo, receiver='right'):
    objects = world_targets(robo)
    matches = [o for o in objects if o['kind'] == 'nut' and o['color'] == 'blue']
    if len(matches) != 1:
        raise RuntimeError('No unique blue nut')
    root = np.asarray(matches[0]['world_root'])
    arm = 'left' if root[0] < 0 else 'right'
    sign = -1.0 if arm == 'left' else 1.0
    target = root + [0.0, 0.0, 0.01]
    empty = robo.set_gripper(arm, robo.CLOSE)
    if empty.holding or float(empty.opening) > 0.02:
        raise RuntimeError('Camera observer not empty')
    fits = []
    for index, x in enumerate([0.0, 0.03]):
        if index:
            robo.home(arm)
        offset = np.array([x, -0.08, 0.2])
        pose = _camera_pose(robo.state().arm(arm), robo.camera_meta('cam_' + arm + '_wrist'), target, target + offset)
        reply = checked(robo, pose['xyz'], arm, pose['pitch'], pose['yaw'], pose['roll'], robo.CLOSE)
        rgb = robo.image('cam_' + arm + '_wrist')
        fit = detect(rgb, robo.camera_meta('cam_' + arm + '_wrist'), root)
        fits.append(fit)
        print({'nut_fit': fit})
        print({'blue_nut_camera': True, 'arm': arm, 'coarse_root': root.tolist(), 'offset': offset.tolist(), 'reply': str(reply)})
    disagreement = float(np.linalg.norm(np.asarray(fits[0]['root'])[:2] - np.asarray(fits[1]['root'])[:2]))
    angles = np.asarray([x['flat_yaw_deg'] for x in fits])
    yawdiff = abs((angles[0] - angles[1] + 30) % 60 - 30)
    if disagreement > 0.002 or yawdiff > 5:
        raise RuntimeError('Nut views disagree before grasp')
    point = np.mean([x['root'] for x in fits], axis=0)
    yaw = float(np.degrees(np.arctan2(np.sin(np.radians(angles * 6)).mean(), np.cos(np.radians(angles * 6)).mean())) / 6)
    robo.set_gripper(arm, robo.OPEN)
    for phase, z in [('approach', 0.85), ('descend', float(point[2] + 0.007))]:
        reply = checked(robo, [float(point[0]), float(point[1]), z], arm, 90.0, yaw, 0.0, robo.OPEN)
        if abs((float(reply.roll) + 180) % 360 - 180) > 5:
            raise RuntimeError('Unsupported alternate grasp roll')
        print({'nut_grasp_phase': phase, 'reply': str(reply)})
    close = robo.set_gripper(arm, robo.CLOSE)
    print({'nut_close': str(close)})
    if not close.holding or close.width_m is None or (not 0.025 < close.width_m < 0.045):
        raise RuntimeError('Unsupported nut grasp reply')
    closure = robo.state().arm(arm)
    held_offset = rotation(closure.eef_quat).T @ (point - np.asarray(closure.tcp_pos))
    reply = checked(robo, [float(point[0]), float(point[1]), 0.87], arm, 90.0, 0.0, 0.0, robo.CLOSE)
    robo.image('cam_head')
    print({'nut_lift': str(reply), 'observed_root': point.tolist(), 'observed_yaw': yaw})
    occupied = [np.asarray(o['world_root'])[:2] for o in objects]
    relay = None
    for candidate in [[0.0, -0.22], [0.0, -0.2], [0.0, -0.24], [-0.04, -0.22], [0.04, -0.22]]:
        if any((np.linalg.norm(np.asarray(candidate) - p) < 0.055 for p in occupied)):
            continue
        valid = True
        for check_arm in ['left', 'right']:
            for z in [0.87, 0.783]:
                preview = robo.preview_move([*candidate, z], arm=check_arm, pitch=90.0, yaw=0.0, roll=0.0, path='line')
                if not preview.get('reachable') or preview.get('note') or preview.get('ik_error'):
                    valid = False
        if valid:
            relay = candidate
            break
    if relay is None:
        raise RuntimeError('No observed-clear relay with both-arm kinematic support')
    for phase, z in [('relay_transport', 0.87), ('relay_place', 0.783)]:
        reply = checked(robo, [*relay, z], arm, 90.0, 0.0, 0.0, robo.CLOSE)
        print({'nut_relay_phase': phase, 'reply': str(reply)})
    robo.set_gripper(arm, robo.OPEN)
    checked(robo, [*relay, 0.87], arm, 90.0, 0.0, 0.0, robo.OPEN)
    robo.home(arm)
    robo.image('cam_head')
    print({'nut_relay_complete': True, 'relay_xy': relay})
    root = np.r_[relay, NUT_ROOT_Z]
    arm = receiver
    target = root + [0.0, 0.0, 0.01]
    empty = robo.set_gripper(arm, robo.CLOSE)
    if empty.holding or float(empty.opening) > 0.02:
        raise RuntimeError('Camera observer not empty')
    fits = []
    for index, x in enumerate([0.0, 0.03]):
        if index:
            robo.home(arm)
        offset = np.array([x, -0.08, 0.2])
        pose = _camera_pose(robo.state().arm(arm), robo.camera_meta('cam_' + arm + '_wrist'), target, target + offset)
        reply = checked(robo, pose['xyz'], arm, pose['pitch'], pose['yaw'], pose['roll'], robo.CLOSE)
        rgb = robo.image('cam_' + arm + '_wrist')
        fit = detect(rgb, robo.camera_meta('cam_' + arm + '_wrist'), root)
        fits.append(fit)
        print({'nut_fit': fit})
        print({'blue_nut_camera': True, 'arm': arm, 'coarse_root': root.tolist(), 'offset': offset.tolist(), 'reply': str(reply)})
    disagreement = float(np.linalg.norm(np.asarray(fits[0]['root'])[:2] - np.asarray(fits[1]['root'])[:2]))
    angles = np.asarray([x['flat_yaw_deg'] for x in fits])
    yawdiff = abs((angles[0] - angles[1] + 30) % 60 - 30)
    if disagreement > 0.002 or yawdiff > 5:
        raise RuntimeError('Nut views disagree before grasp')
    point = np.mean([x['root'] for x in fits], axis=0)
    yaw = float(np.degrees(np.arctan2(np.sin(np.radians(angles * 6)).mean(), np.cos(np.radians(angles * 6)).mean())) / 6)
    robo.set_gripper(arm, robo.OPEN)
    for phase, z in [('approach', 0.85), ('descend', float(point[2] + 0.007))]:
        reply = checked(robo, [float(point[0]), float(point[1]), z], arm, 90.0, yaw, 0.0, robo.OPEN)
        if abs((float(reply.roll) + 180) % 360 - 180) > 5:
            raise RuntimeError('Unsupported alternate grasp roll')
        print({'nut_grasp_phase': phase, 'reply': str(reply)})
    close = robo.set_gripper(arm, robo.CLOSE)
    print({'nut_close': str(close)})
    if not close.holding or close.width_m is None or (not 0.025 < close.width_m < 0.045):
        raise RuntimeError('Unsupported nut grasp reply')
    closure = robo.state().arm(arm)
    held_offset = rotation(closure.eef_quat).T @ (point - np.asarray(closure.tcp_pos))
    reply = checked(robo, [float(point[0]), float(point[1]), 0.87], arm, 90.0, 0.0, 0.0, robo.CLOSE)
    robo.image('cam_head')
    print({'nut_lift': str(reply), 'observed_root': point.tolist(), 'observed_yaw': yaw})
    print({'receiving_grasp_complete': True})
    return {'arm': arm, 'held_offset_eef': held_offset.tolist()}

def detect_flat_nut_color(rgb, meta, coarse, color):
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    a = np.asarray(rgb, float)
    r, g, b = a.transpose(2, 0, 1)

    def project(xyz):
        q = (np.asarray(xyz) - T[:3, 3]) @ T[:3, :3]
        return np.column_stack((K[0, 0] * q[:, 0] / -q[:, 2] + K[0, 2], K[1, 1] * q[:, 1] / q[:, 2] + K[1, 2]))
    xy = project([coarse])[0]
    yy, xx = np.indices(r.shape)
    depth = abs(((np.asarray(coarse) - T[:3, 3]) @ T[:3, :3])[2])
    radius = max(60.0, 0.03 * K[0, 0] / depth)
    if color == 'pink':
        mask = (r > 160) & (b > 150) & (g > 85) & (b - g > 10) & (r - g > 10)
    elif color == 'white':
        mask = (r > 152) & (g > 152) & (b > 146) & (np.maximum(np.maximum(r, g), b) - np.minimum(np.minimum(r, g), b) < 42)
    elif color == 'yellow':
        mask = (r > 142) & (g > 122) & (b < 140) & (g - b > 72) & (r - b > 90) & (g > 0.72 * r)
    elif color == 'blue':
        mask = (b > 150) & (b - r > 40) & (b - g > 40)
    elif color == 'red':
        mask = (r > 160) & (r - g > 80) & (r - b > 80)
    else:
        raise ValueError('Unsupported nut color')
    mask &= (abs(xx - xy[0]) < radius) & (abs(yy - xy[1]) < radius)
    ll, n = label(mask)
    parts = [np.argwhere(ll == i) for i in range(1, n + 1)]
    parts = [v for v in parts if len(v) > 200 and np.linalg.norm(v.mean(0)[::-1] - xy) < radius * 0.6]
    if len(parts) != 1:
        raise RuntimeError('No unique pink nut component')
    pixels = parts[0][:, ::-1]
    observed = pixels[ConvexHull(pixels).vertices].astype(float)
    x, y, yaw, radius, radius_measured, rms = _fit_flat_hex(project, observed, coarse, 0.03, color=color)
    if rms > 1.5:
        raise RuntimeError('Hex silhouette fit residual too large')
    return {'root': [x, y, NUT_ROOT_Z], 'flat_yaw_deg': float((yaw + 30) % 60 - 30), 'pixel_rms': rms, 'pixels': len(pixels), 'ring_radius_m': radius, 'ring_radius_measured': radius_measured, 'scope': 'Flat table nut only; compact static hex prior, no held-pose claim'}

def detect_white_bolt_cap(rgb, meta, coarse):
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    top = np.asarray(coarse) + [0, 0, RGB_BOLT_GEOMETRY['white']['height']]
    q = T[:3, :3].T @ (top - T[:3, 3])
    pixel = np.array([K[1, 1] * q[1] / q[2] + K[1, 2], K[0, 0] * q[0] / -q[2] + K[0, 2]])
    a = np.asarray(rgb, float)
    r, g, b = a.transpose(2, 0, 1)
    yy, xx = np.indices(r.shape)
    mask = (r > 200) & (g > 200) & (b > 200) & (np.maximum(np.maximum(r, g), b) - np.minimum(np.minimum(r, g), b) < 35) & (abs(yy - pixel[0]) < 35) & (abs(xx - pixel[1]) < 35)
    rc = np.argwhere(mask)
    if len(rc) < 300:
        raise RuntimeError('Insufficient blue silhouette')
    upper = []
    for col in np.unique(rc[:, 1]):
        row = rc[rc[:, 1] == col, 0].min()
        if row <= rc[:, 0].min() + 14:
            upper.append([row, col])
    pts = []
    for row, col in upper:
        ray = np.linalg.solve(K, [col, row, 1.0]) * [1, -1, -1]
        d = T[:3, :3] @ ray
        t = (0.8174 - T[2, 3]) / d[2]
        pts.append((T[:3, 3] + t * d)[:2])
    pts = np.asarray(pts)
    if len(pts) < 20:
        raise RuntimeError('Too little upper rim')
    radius = 0.01
    fit = least_squares(lambda center: np.linalg.norm(pts - center, axis=1) - radius, np.asarray(coarse)[:2], loss='soft_l1', f_scale=0.0003)
    center = fit.x
    resid = float(np.median(abs(np.linalg.norm(pts - center, axis=1) - radius)))
    if resid > 0.0005 or np.linalg.norm(center - np.asarray(coarse)[:2]) > 0.005:
        raise RuntimeError('Upper arc geometry disagrees')
    return {'root': [float(center[0]), float(center[1]), 0.765], 'arc_pixels': len(pts), 'median_radius_residual_m': resid, 'radius_prior_m': radius}

def detect_yellow_bolt_cap(rgb, meta, coarse):
    # Yellow-bolt height and cap plane: RGB fit; docs/fasten_screws/applied_values.json (rgb_derived_values, RGB_BOLT_GEOMETRY).
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    top = np.asarray(coarse) + [0, 0, RGB_BOLT_GEOMETRY['yellow']['height']]
    q = T[:3, :3].T @ (top - T[:3, 3])
    pixel = np.array([K[1, 1] * q[1] / q[2] + K[1, 2], K[0, 0] * q[0] / -q[2] + K[0, 2]])
    a = np.asarray(rgb, float)
    r, g, b = a.transpose(2, 0, 1)
    yy, xx = np.indices(r.shape)
    mask = (r > 200) & (g > 180) & (b < 180) & (g - b > 50) & (abs(yy - pixel[0]) < 35) & (abs(xx - pixel[1]) < 35)
    rc = np.argwhere(mask)
    if len(rc) < 300:
        raise RuntimeError('Insufficient blue silhouette')
    upper = []
    for col in np.unique(rc[:, 1]):
        row = rc[rc[:, 1] == col, 0].min()
        if row <= rc[:, 0].min() + 14:
            upper.append([row, col])
    pts = []
    for row, col in upper:
        ray = np.linalg.solve(K, [col, row, 1.0]) * [1, -1, -1]
        d = T[:3, :3] @ ray
        t = (RGB_BOLT_GEOMETRY['yellow']['cap_z'] - T[2, 3]) / d[2]
        pts.append((T[:3, 3] + t * d)[:2])
    pts = np.asarray(pts)
    if len(pts) < 20:
        raise RuntimeError('Too little upper rim')
    radius = 0.01
    fit = least_squares(lambda center: np.linalg.norm(pts - center, axis=1) - radius, np.asarray(coarse)[:2], loss='soft_l1', f_scale=0.0003)
    center = fit.x
    resid = float(np.median(abs(np.linalg.norm(pts - center, axis=1) - radius)))
    if resid > 0.0005 or np.linalg.norm(center - np.asarray(coarse)[:2]) > 0.005:
        raise RuntimeError('Upper arc geometry disagrees')
    return {'root': [float(center[0]), float(center[1]), 0.765], 'arc_pixels': len(pts), 'median_radius_residual_m': resid, 'radius_prior_m': radius}

def acquire_white_cap(robo, color):
    detector = {'white': detect_white_bolt_cap, 'yellow': detect_yellow_bolt_cap}[color]
    objects = world_targets(robo)
    matches = observed_bolt_matches(objects, color)
    if len(matches) != 1:
        raise RuntimeError('No unique blue bolt')
    root = np.asarray(matches[0]['world_root'])
    arm = 'left' if root[0] > 0 else 'right'
    sign = -1.0 if arm == 'left' else 1.0
    target = root + [0.0, 0.0, 0.02]
    close = robo.set_gripper(arm, robo.CLOSE)
    if close.holding or float(close.opening) > 0.02:
        raise RuntimeError('Observer not empty')
    positions = []
    for index, y in enumerate([-0.02, 0.04]):
        if index:
            home = robo.home(arm)
            if not home.reached:
                raise RuntimeError('Observer home failed before second view')
        offsets = [np.array([sign * 0.1, y, 0.2])]
        if index:
            offsets.extend([np.array([sign * 0.12, y, 0.2]), np.array([sign * 0.1, 0.02, 0.2])])
        pose = None
        for offset in offsets:
            proposed = _camera_pose(robo.state().arm(arm), robo.camera_meta('cam_' + arm + '_wrist'), target, target + offset)
            preview = robo.preview_move(proposed['xyz'], arm=arm, pitch=proposed['pitch'], yaw=proposed['yaw'], roll=proposed['roll'], path='line')
            if preview.get('reachable') and (not preview.get('ik_error')) and (not preview.get('note')):
                pose = proposed
                break
        if pose is None:
            raise RuntimeError('No exact bounded second cap camera pose')
        reply = checked(robo, pose['xyz'], arm, pose['pitch'], pose['yaw'], pose['roll'], robo.CLOSE)
        rgb = robo.image('cam_' + arm + '_wrist')
        pred = detector(rgb, robo.camera_meta('cam_' + arm + '_wrist'), root)
        positions.append(pred['root'])
        print({'pregrasp_cap_fit': pred})
        print({'blue_cap_camera': True, 'arm': arm, 'coarse_root': root.tolist(), 'offset': offset.tolist(), 'reply': str(reply)})
    h = robo.home('both')
    if not h.reached:
        raise RuntimeError('Empty arms failed home before grasp')
    disagreement = float(np.linalg.norm(np.asarray(positions[0]) - positions[1]))
    if disagreement > 0.0015:
        raise RuntimeError('Cap views disagree')
    return {'root': np.mean(positions, axis=0).tolist(), 'view_disagreement_m': disagreement}

