_exact_checked = checked

def checked(robo, xyz, arm, pitch, yaw, roll, gripper):
    if abs(pitch - 90) < 1e-09 and abs(yaw - 150) < 1e-09 and (abs(roll) < 1e-09):
        original = robo.preview_move(list(xyz), arm=arm, pitch=pitch, yaw=yaw, roll=roll, path='line')
        if not original.get('reachable') or original.get('ik_error') or original.get('note'):
            print({'thread_yaw_original_preview_rejected': original, 'requested_yaw': yaw})
            for alternate in [149.0, 148.0]:
                preview = robo.preview_move(list(xyz), arm=arm, pitch=pitch, yaw=alternate, roll=roll, path='line')
                if preview.get('reachable') and (not preview.get('ik_error')) and (not preview.get('note')):
                    print({'thread_yaw_alternate_target': alternate, 'original_target': yaw, 'task_requirement_unchanged': True})
                    return _exact_checked(robo, xyz, arm, pitch, alternate, roll, gripper)
    return _exact_checked(robo, xyz, arm, pitch, yaw, roll, gripper)
_stage_colors = None
_stage_index = 0

def run_next(robo):
    global _stage_colors, _stage_index
    if _stage_colors is None:
        objects = world_targets(robo)
        nuts = {o['color'] for o in objects if o['kind'] == 'nut'}
        bolts = {o['color'] for o in objects if o['kind'] == 'bolt'}
        if nuts != bolts or len(nuts) != 3 or (not nuts.issubset({'blue', 'red', 'pink', 'white', 'yellow'})):
            raise RuntimeError('No unique three-color task correspondence')
        remember_initial_bolts(objects)
        _stage_colors = [c for c in ['blue', 'red', 'pink', 'white', 'yellow'] if c in nuts]
    if _stage_index >= len(_stage_colors):
        raise RuntimeError('All three stages already attempted')
    color = _stage_colors[_stage_index]
    acquire_first = {'blue': blue_acquire_first, 'red': red_independent_first, 'pink': pink_acquire_first}
    print({'pair_start': color, 'action_count': str(robo.action_count())})
    arm = acquire_first[color](robo) if color in acquire_first else aux_acquire_first(robo, color)
    finish_pair(robo, arm, final_pair=_stage_index == len(_stage_colors) - 1)
    _stage_index += 1
    print({'pair_finished': color, 'episode_outcome_authoritative': True})
    return {'stage_index': _stage_index - 1, 'color': color, 'more': _stage_index < len(_stage_colors), 'episode_outcome_authoritative': True}

def run(robo):
    raise RuntimeError('Use run_next: one colour pair per call')

def acquire_aux_nut(robo, color, receiver):
    objects = world_targets(robo)
    matches = [o for o in objects if o['kind'] == 'nut' and o['color'] == color]
    if len(matches) != 1:
        raise RuntimeError('No unique blue nut')
    root = np.asarray(matches[0]['world_root'])
    arm = 'left' if root[0] < 0 else 'right'
    sign = -1.0 if arm == 'left' else 1.0
    target = root + [0.0, 0.0, 0.01]
    empty = robo.set_gripper(arm, robo.CLOSE)
    if empty.holding or float(empty.opening) > 0.02:
        raise RuntimeError('Camera observer not empty')
    fits = collect_nut_views(robo, color, root, arm)
    disagreement = float(np.linalg.norm(np.asarray(fits[0]['root'])[:2] - np.asarray(fits[1]['root'])[:2]))
    angles = np.asarray([x['flat_yaw_deg'] for x in fits])
    yawdiff = abs((angles[0] - angles[1] + 30) % 60 - 30)
    if disagreement > 0.002 or yawdiff > 5:
        raise RuntimeError('Nut views disagree before grasp')
    point = np.mean([x['root'] for x in fits], axis=0)
    yaw = float(np.degrees(np.arctan2(np.sin(np.radians(angles * 6)).mean(), np.cos(np.radians(angles * 6)).mean())) / 6)
    robo.set_gripper(arm, robo.OPEN)
    for phase, z in [('approach', 0.85), ('descend', float(point[2] + 0.007))]:
        reply = checked(robo, [float(point[0]), float(point[1]), z], arm, 90.0, yaw, 0.0, robo.OPEN)
        if abs((float(reply.roll) + 180) % 360 - 180) > 5:
            raise RuntimeError('Unsupported alternate grasp roll')
        print({'nut_grasp_phase': phase, 'reply': str(reply)})
    close = robo.set_gripper(arm, robo.CLOSE)
    print({'nut_close': str(close)})
    if not close.holding or close.width_m is None or (not 0.025 < close.width_m < 0.045):
        raise RuntimeError('Unsupported nut grasp reply')
    closure = robo.state().arm(arm)
    held_offset = rotation(closure.eef_quat).T @ (point - np.asarray(closure.tcp_pos))
    reply = checked(robo, [float(point[0]), float(point[1]), 0.87], arm, 90.0, 0.0, 0.0, robo.CLOSE)
    robo.image('cam_head')
    print({'nut_lift': str(reply), 'observed_root': point.tolist(), 'observed_yaw': yaw})
    if arm == receiver:
        return {'arm': arm, 'held_offset_eef': held_offset.tolist()}
    occupied = [np.asarray(o['world_root'])[:2] for o in objects]
    relay = None
    for candidate in [[0.0, -0.22], [0.0, -0.2], [0.0, -0.24], [-0.04, -0.22], [0.04, -0.22]]:
        if any((np.linalg.norm(np.asarray(candidate) - p) < 0.055 for p in occupied)):
            continue
        valid = True
        for check_arm in ['left', 'right']:
            for z in [0.87, 0.783]:
                preview = robo.preview_move([*candidate, z], arm=check_arm, pitch=90.0, yaw=0.0, roll=0.0, path='line')
                if not preview.get('reachable') or preview.get('note') or preview.get('ik_error'):
                    valid = False
        if valid:
            relay = candidate
            break
    if relay is None:
        raise RuntimeError('No observed-clear relay with both-arm kinematic support')
    for phase, z in [('relay_transport', 0.87), ('relay_place', 0.783)]:
        reply = checked(robo, [*relay, z], arm, 90.0, 0.0, 0.0, robo.CLOSE)
        print({'nut_relay_phase': phase, 'reply': str(reply)})
    robo.set_gripper(arm, robo.OPEN)
    checked(robo, [*relay, 0.87], arm, 90.0, 0.0, 0.0, robo.OPEN)
    robo.home(arm)
    robo.image('cam_head')
    print({'nut_relay_complete': True, 'relay_xy': relay})
    root = np.r_[relay, NUT_ROOT_Z]
    arm = receiver
    target = root + [0.0, 0.0, 0.01]
    empty = robo.set_gripper(arm, robo.CLOSE)
    if empty.holding or float(empty.opening) > 0.02:
        raise RuntimeError('Camera observer not empty')
    fits = []
    near_center_left = arm == 'left' and root[0] > -0.12
    for index, x in enumerate([-0.03, -0.06] if near_center_left else [0.0, 0.03]):
        if index:
            home = robo.home(arm)
            if not home.reached:
                raise RuntimeError('Between-view home failed')
        offset = np.array([x, -0.08, 0.25 if near_center_left else 0.2])
        pose = _camera_pose(robo.state().arm(arm), robo.camera_meta('cam_' + arm + '_wrist'), target, target + offset)
        reply = checked(robo, pose['xyz'], arm, pose['pitch'], pose['yaw'], pose['roll'], robo.CLOSE)
        rgb = robo.image('cam_' + arm + '_wrist')
        fit = detect_flat_nut_color(rgb, robo.camera_meta('cam_' + arm + '_wrist'), root, color)
        fits.append(fit)
        print({'nut_fit': fit})
        print({'blue_nut_camera': True, 'arm': arm, 'coarse_root': root.tolist(), 'offset': offset.tolist(), 'reply': str(reply)})
    disagreement = float(np.linalg.norm(np.asarray(fits[0]['root'])[:2] - np.asarray(fits[1]['root'])[:2]))
    angles = np.asarray([x['flat_yaw_deg'] for x in fits])
    yawdiff = abs((angles[0] - angles[1] + 30) % 60 - 30)
    if disagreement > 0.002 or yawdiff > 5:
        raise RuntimeError('Nut views disagree before grasp')
    point = np.mean([x['root'] for x in fits], axis=0)
    yaw = float(np.degrees(np.arctan2(np.sin(np.radians(angles * 6)).mean(), np.cos(np.radians(angles * 6)).mean())) / 6)
    robo.set_gripper(arm, robo.OPEN)
    for phase, z in [('approach', 0.85), ('descend', float(point[2] + 0.007))]:
        reply = checked(robo, [float(point[0]), float(point[1]), z], arm, 90.0, yaw, 0.0, robo.OPEN)
        if abs((float(reply.roll) + 180) % 360 - 180) > 5:
            raise RuntimeError('Unsupported alternate grasp roll')
        print({'nut_grasp_phase': phase, 'reply': str(reply)})
    close = robo.set_gripper(arm, robo.CLOSE)
    print({'nut_close': str(close)})
    if not close.holding or close.width_m is None or (not 0.025 < close.width_m < 0.045):
        raise RuntimeError('Unsupported nut grasp reply')
    closure = robo.state().arm(arm)
    held_offset = rotation(closure.eef_quat).T @ (point - np.asarray(closure.tcp_pos))
    reply = checked(robo, [float(point[0]), float(point[1]), 0.87], arm, 90.0, 0.0, 0.0, robo.CLOSE)
    robo.image('cam_head')
    print({'nut_lift': str(reply), 'observed_root': point.tolist(), 'observed_yaw': yaw})
    print({'receiving_grasp_complete': True})
    return {'arm': arm, 'held_offset_eef': held_offset.tolist()}
_initial_bolt_anchors = {}

def remember_initial_bolts(objects):
    global _initial_bolt_anchors
    colors = {o['color'] for o in objects if o['kind'] == 'bolt'}
    _initial_bolt_anchors = {color: np.asarray(matches[0]['world_root']).copy() for color in colors if len((matches := [o for o in objects if o['kind'] == 'bolt' and o['color'] == color])) == 1}

def observed_bolt_matches(objects, color):
    matches = [o for o in objects if o['kind'] == 'bolt' and o['color'] == color]
    if len(matches) > 1 and color in _initial_bolt_anchors:
        anchor = _initial_bolt_anchors[color]
        matches = [o for o in matches if np.linalg.norm(np.asarray(o['world_root'])[:2] - anchor[:2]) < 0.025]
    return matches
_raw_world_targets = world_targets
_initial_object_anchors = {}
_remember_initial_bolts_plain = remember_initial_bolts

def remember_initial_bolts(objects):
    global _initial_object_anchors
    _remember_initial_bolts_plain(objects)
    _initial_object_anchors = {(o['color'], o['kind']): np.asarray(o['world_root']).copy() for o in objects if sum((x['color'] == o['color'] and x['kind'] == o['kind'] for x in objects)) == 1}

def world_targets(robo):
    objects = _raw_world_targets(robo)
    if not _initial_object_anchors:
        return objects
    meta = robo.camera_meta('cam_head')
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    for o in objects:
        matches = [(kind, float(np.linalg.norm(np.asarray(o['world_root'])[:2] - pos[:2]))) for (color, kind), pos in _initial_object_anchors.items() if color == o['color']]
        matches.sort(key=lambda x: x[1])
        if not matches or matches[0][1] > 0.025 or (len(matches) > 1 and matches[1][1] - matches[0][1] < 0.015):
            continue
        if o['kind'] != matches[0][0]:
            print({'observed_identity_correction': o['color'], 'old_kind': o['kind'], 'new_kind': matches[0][0], 'association_distance_m': matches[0][1]})
            o['kind'] = matches[0][0]
            x, y = o['pixel_xy']
            ray = T[:3, :3] @ (np.linalg.solve(K, [x, y, 1.0]) * [1, -1, -1])
            z = NUT_ROOT_Z if o['kind'] == 'nut' else 0.765
            o['world_root'] = (T[:3, 3] + ray * (z - T[2, 3]) / ray[2]).tolist()
    return objects

def collect_nut_views(robo, color, root, arm):
    root = np.asarray(root)
    target = root + [0.0, 0.0, 0.01]
    near = arm == 'left' and root[0] > -0.12
    offsets = [[-0.03, -0.08, 0.25], [-0.06, -0.08, 0.25], [-0.05, -0.1, 0.28], [-0.08, -0.08, 0.25]] if near else [[0.0, -0.08, 0.2], [0.03, -0.08, 0.2], [-0.03, -0.08, 0.24], [0.03, -0.12, 0.24]]
    fits = []
    for index, offset in enumerate(offsets):
        if index:
            home = robo.home(arm)
            if not home.reached:
                raise RuntimeError('Nut observer home stopped')
        pose = _camera_pose(robo.state().arm(arm), robo.camera_meta('cam_' + arm + '_wrist'), target, target + offset)
        pre = robo.preview_move(pose['xyz'], arm=arm, pitch=pose['pitch'], yaw=pose['yaw'], roll=pose['roll'], path='line')
        if not pre.get('reachable') or pre.get('note') or pre.get('ik_error'):
            print({'nut_view_rejected': index, 'preview': str(pre)})
            continue
        rec = checked(robo, pose['xyz'], arm, pose['pitch'], pose['yaw'], pose['roll'], robo.CLOSE)
        rgb = robo.image('cam_' + arm + '_wrist')
        meta = robo.camera_meta('cam_' + arm + '_wrist')
        try:
            fit = detect_flat_nut_color(rgb, meta, root, color)
        except RuntimeError as exc:
            print({'nut_view_abstention': index, 'reason': str(exc), 'offset': offset})
            continue
        fits.append(fit)
        print({'nut_fit': fit, 'view_index': index, 'offset': offset, 'reply': str(rec), 'actual_camera_meta': meta})
        if len(fits) == 2:
            return fits
    raise RuntimeError('Nut remains unobservable after four bounded views')

def guarded_empty_home_both(robo):
    for arm in ['left', 'right']:
        st = robo.state().arm(arm)
        if float(st.gripper) < 0.95:
            raise RuntimeError('Both jaws must be visibly empty/open before combined home')
        if float(st.tcp_pos[2]) < 0.87:
            goal = np.asarray(st.tcp_pos) + [0.0, 0.0, 0.06]
            preview = robo.preview_move(goal.tolist(), arm=arm, pitch=float(st.pitch), yaw=float(st.yaw), roll=float(st.roll), path='line')
            print({'mandatory_axial_home_lift_preview': preview, 'arm': arm})
            if not preview.get('reachable') or preview.get('ik_error') or preview.get('note') or (goal[2] < 0.87):
                raise RuntimeError('Home axial lift clearance unsupported')
    reply = robo.home('both')
    print({'combined_empty_home': str(reply), 'lift_and_joint_controller_unchanged': True})
    if not reply.reached and (not getattr(reply, 'truncated', False)):
        raise RuntimeError('Combined empty home did not reach')
    return {'physical_strokes_complete': True, 'episode_outcome_authoritative': True}
